CREATE TABLE IF NOT EXISTS "system_dept" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(30) NOT NULL DEFAULT '',
    "parent_id" bigint NOT NULL DEFAULT '0',
    "sort" int NOT NULL DEFAULT '0',
    "leader_user_id" bigint DEFAULT NULL,
    "phone" varchar(11) DEFAULT NULL,
    "email" varchar(50) DEFAULT NULL,
    "status" tinyint NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default  '0',
    PRIMARY KEY ("id")
) COMMENT '部门表';

CREATE TABLE IF NOT EXISTS "system_role" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(30) NOT NULL,
    "code" varchar(100) NOT NULL,
    "sort" int NOT NULL,
    "category_id" bigint DEFAULT NULL,
    "data_scope" tinyint NOT NULL DEFAULT '1',
    "data_scope_dept_ids" varchar(500) NOT NULL DEFAULT '',
    "status" tinyint NOT NULL,
    "type" tinyint NOT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default  '0',
    PRIMARY KEY ("id")
) COMMENT '角色信息表';

CREATE TABLE IF NOT EXISTS "system_user_role" (
     "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
     "user_id" bigint NOT NULL,
     "role_id" bigint NOT NULL,
     "creator" varchar(64) DEFAULT '',
     "create_time" timestamp DEFAULT NULL,
     "updater" varchar(64) DEFAULT '',
     "update_time" timestamp DEFAULT NULL,
     "deleted" bit DEFAULT FALSE,
    "tenant_id" bigint not null default  '0',
    PRIMARY KEY ("id")
) COMMENT '用户和角色关联表';

CREATE TABLE IF NOT EXISTS "system_users" (
    "id" bigint not null GENERATED BY DEFAULT AS IDENTITY,
    "username" varchar(30) not null,
    "password" varchar(100) not null default '',
    "nickname" varchar(30) not null,
    "remark" varchar(500) default null,
    "dept_id" bigint default null,
    "post_ids" varchar(255) default null,
    "email" varchar(50) default '',
    "mobile" varchar(11) default '',
    "sex" tinyint default '0',
    "avatar" varchar(100) default '',
    "status" tinyint not null default '0',
    "login_ip" varchar(50) default '',
    "login_date" timestamp default null,
    "password_update_time" timestamp DEFAULT NULL,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    "tenant_id" bigint not null default  '0',
    primary key ("id")
) comment '用户信息表';

CREATE TABLE IF NOT EXISTS "showroom_public_site_binding" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "site_key" varchar(64) NOT NULL,
    "stage" varchar(16) NOT NULL,
    "tenant_id" bigint NOT NULL,
    "display_name" varchar(128) NOT NULL,
    "enabled" bit NOT NULL DEFAULT TRUE,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_showroom_public_site_stage" UNIQUE ("site_key", "stage")
);

CREATE TABLE IF NOT EXISTS "system_notify_template" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar NOT NULL,
    "code" varchar NOT NULL,
    "nickname" varchar NOT NULL,
    "content" varchar NOT NULL,
    "type" varchar NOT NULL,
    "params" varchar,
    "status" varchar NOT NULL,
    "remark" varchar,
    "creator" varchar DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '站内信模板表';

CREATE TABLE IF NOT EXISTS "system_notify_message" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "user_type" varchar NOT NULL,
    "business_key" varchar(255) DEFAULT NULL,
    "template_id" bigint NOT NULL,
    "template_code" varchar NOT NULL,
    "template_nickname" varchar NOT NULL,
    "template_content" varchar NOT NULL,
    "template_type" int NOT NULL,
    "template_params" varchar NOT NULL,
    "read_status" bit NOT NULL,
    "read_time" varchar,
    "creator" varchar DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default  '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_system_notify_message_tenant_business_key" UNIQUE ("tenant_id", "business_key")
) COMMENT '站内信消息表';

CREATE TABLE IF NOT EXISTS "showroom_company" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "company_code" varchar(64) NOT NULL,
    "display_name" varchar(255) NOT NULL,
    "display_name_en" varchar(255) DEFAULT NULL,
    "company_type" varchar(32) NOT NULL,
    "current_revision_id" bigint DEFAULT NULL,
    "current_revision_no" int DEFAULT NULL,
    "incomplete_flag" bit NOT NULL DEFAULT FALSE,
    "frozen_flag" bit NOT NULL DEFAULT FALSE,
    "frozen_hall_count" int NOT NULL DEFAULT 0,
    "status" varchar(32) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_showroom_company_code" UNIQUE ("tenant_id", "company_code")
);

CREATE TABLE IF NOT EXISTS "showroom_company_revision" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "company_id" bigint NOT NULL,
    "revision_no" int NOT NULL,
    "status" varchar(32) NOT NULL,
    "development_history" clob DEFAULT NULL,
    "development_history_en" clob DEFAULT NULL,
    "park_introduction" clob DEFAULT NULL,
    "park_introduction_en" clob DEFAULT NULL,
    "incubation_platform" clob DEFAULT NULL,
    "incubation_platform_en" clob DEFAULT NULL,
    "subsidiary_overview" clob DEFAULT NULL,
    "subsidiary_overview_en" clob DEFAULT NULL,
    "stock_info" clob DEFAULT NULL,
    "stock_info_en" clob DEFAULT NULL,
    "cover_image" clob DEFAULT NULL,
    "core_manufacturing_capability" clob DEFAULT NULL,
    "core_manufacturing_capability_en" clob DEFAULT NULL,
    "honors_awards" clob DEFAULT NULL,
    "honors_awards_en" clob DEFAULT NULL,
    "display_name_snapshot" varchar(255) DEFAULT NULL,
    "display_name_en_snapshot" varchar(255) DEFAULT NULL,
    "company_type_snapshot" varchar(32) DEFAULT NULL,
    "submitted_by" bigint DEFAULT NULL,
    "approved_by" bigint DEFAULT NULL,
    "published_at" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_showroom_company_revision_no" UNIQUE ("tenant_id", "company_id", "revision_no")
);

CREATE TABLE IF NOT EXISTS "showroom_product" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_master_id" bigint DEFAULT NULL,
    "product_code" varchar(64) NOT NULL,
    "legacy_product_code" varchar(64) DEFAULT NULL,
    "current_revision_id" bigint DEFAULT NULL,
    "current_revision_no" int DEFAULT NULL,
    "incomplete_flag" bit NOT NULL DEFAULT FALSE,
    "frozen_flag" bit NOT NULL DEFAULT FALSE,
    "frozen_hall_count" int NOT NULL DEFAULT 0,
    "status" varchar(32) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_showroom_product_code" UNIQUE ("tenant_id", "product_code"),
    CONSTRAINT "uk_showroom_product_legacy_code" UNIQUE ("tenant_id", "legacy_product_code")
);

CREATE TABLE IF NOT EXISTS "showroom_keyword" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
